static inline lt48_status lt48_pic_applet_identity_run(const lt48_pic_applet_identity_profile *p,
 const lt48_pic_source_resources *resources,lt48_pic_source_session *active_session,
 lt48_pic_source_runner runner,void *context,lt48_pic_source_identity_result *result) {
 if(result)memset(result,0,sizeof(*result));
 if(!p||!resources||!active_session||!result)return LT48_INVALID_ARGUMENT;
 if(!p->source_sha256||strlen(p->source_sha256)!=64)return LT48_FORMAT_ERROR;
 unsigned char sha[32];
 for(unsigned i=0;i<32;i++){unsigned value=0;
  for(unsigned j=0;j<2;j++){unsigned c=(unsigned char)p->source_sha256[2*i+j];
   if(c>='0'&&c<='9')c-='0';else if(c>='a'&&c<='f')c=c-'a'+10;else return LT48_FORMAT_ERROR;
   value=(value<<4)|c;}sha[i]=(unsigned char)value;}
 if(!lt48_pic_source_resources_matches_binding_internal(resources,sha,p->family,p->pinmap)||
    !lt48_pic_source_session_matches_origin_internal(active_session,resources))return LT48_SAFETY_REJECTED;
 return lt48_pic_source_identity_session(active_session,&p->plan,runner,context,result);
}
